                    Float massOverride, int totalSteps, List<Impulse> impulses) {
        this.gravityX = gravityX;
        this.gravityY = gravityY;
        this.bodyX = bodyX;
        this.bodyY = bodyY;
        this.massOverride = massOverride;
        this.totalSteps = totalSteps;
        this.impulses = impulses;
    }

